using System.ComponentModel.DataAnnotations; using System.Security.Claims; using Marina.Domain.Commerce; using Marina.Persistence.Data; using Marina.Persistence.Identity; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace Marina.Api.Controllers;
[ApiController,Authorize,Route("api/v1/customer")]
public sealed class CustomerController(MarinaDbContext db,UserManager<AppUser>users):ControllerBase{
 public sealed record AddressRequest([Required,MaxLength(60)]string Label,[Required,MaxLength(100)]string Recipient,[Required,Phone,MaxLength(30)]string Phone,[Required,MaxLength(100)]string City,[Required,MaxLength(240)]string Line1,[MaxLength(20)]string?PostalCode,bool IsDefault);public sealed record ProfileRequest([Required,MaxLength(100)]string DisplayName,[Phone,MaxLength(30)]string?Phone);
 [HttpGet("profile")]public async Task<ActionResult>Profile(){var user=await users.FindByIdAsync(UserId().ToString())??throw new UnauthorizedAccessException();return Ok(new{user.Id,user.Email,user.DisplayName,user.PhoneNumber});}
 [HttpPut("profile")]public async Task<IActionResult>UpdateProfile(ProfileRequest r){var user=await users.FindByIdAsync(UserId().ToString())??throw new UnauthorizedAccessException();user.DisplayName=r.DisplayName.Trim();user.PhoneNumber=r.Phone?.Trim();var result=await users.UpdateAsync(user);if(!result.Succeeded)throw new ArgumentException(string.Join(" ",result.Errors.Select(x=>x.Description)));return NoContent();}
 [HttpGet("addresses")]public async Task<ActionResult>Addresses()=>Ok(await db.Addresses.AsNoTracking().Where(x=>x.UserId==UserId()&&!x.IsDeleted).OrderByDescending(x=>x.IsDefault).ToListAsync());
 [HttpPost("addresses")]public async Task<ActionResult>AddAddress(AddressRequest r){await using var transaction=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);if(r.IsDefault)await db.Addresses.Where(x=>x.UserId==UserId()).ExecuteUpdateAsync(x=>x.SetProperty(a=>a.IsDefault,false));var address=new Address{UserId=UserId(),Label=r.Label.Trim(),Recipient=r.Recipient.Trim(),Phone=r.Phone.Trim(),City=r.City.Trim(),Line1=r.Line1.Trim(),PostalCode=r.PostalCode?.Trim(),IsDefault=r.IsDefault};db.Addresses.Add(address);await db.SaveChangesAsync();await transaction.CommitAsync();return Created("",address);}
 [HttpPut("addresses/{id:guid}")]public async Task<IActionResult>UpdateAddress(Guid id,AddressRequest r){await using var transaction=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var a=await db.Addresses.SingleOrDefaultAsync(x=>x.Id==id&&x.UserId==UserId()&&!x.IsDeleted)??throw new KeyNotFoundException("Address not found.");if(r.IsDefault)await db.Addresses.Where(x=>x.UserId==UserId()&&x.Id!=id).ExecuteUpdateAsync(x=>x.SetProperty(y=>y.IsDefault,false));a.Label=r.Label.Trim();a.Recipient=r.Recipient.Trim();a.Phone=r.Phone.Trim();a.City=r.City.Trim();a.Line1=r.Line1.Trim();a.PostalCode=r.PostalCode?.Trim();a.IsDefault=r.IsDefault;await db.SaveChangesAsync();await transaction.CommitAsync();return NoContent();}
 [HttpDelete("addresses/{id:guid}")]public async Task<IActionResult>DeleteAddress(Guid id){var a=await db.Addresses.SingleOrDefaultAsync(x=>x.Id==id&&x.UserId==UserId())??throw new KeyNotFoundException("Address not found.");a.IsDeleted=true;await db.SaveChangesAsync();return NoContent();}
 [HttpGet("favorites")]public async Task<ActionResult>Favorites([FromQuery]string culture="en"){culture=culture.Equals("ar",StringComparison.OrdinalIgnoreCase)?"ar":"en";return Ok(await db.Favorites.AsNoTracking().Where(x=>x.UserId==UserId()).Join(db.Products.Where(p=>p.IsActive&&!p.IsDeleted),x=>x.ProductId,x=>x.Id,(f,p)=>new{p.Id,p.Slug,Name=p.Translations.Where(t=>t.Culture==culture).Select(t=>t.Name).FirstOrDefault(),VariantId=p.Variants.Where(v=>v.IsActive&&!v.IsDeleted).OrderBy(v=>v.Price).Select(v=>v.Id).FirstOrDefault(),Image=p.Images.OrderBy(i=>i.SortOrder).Select(i=>i.Url).FirstOrDefault(),Price=p.Variants.Where(v=>v.IsActive&&!v.IsDeleted).Min(v=>v.Price)}).ToListAsync());}
 [HttpPost("favorites/{productId:guid}")]public async Task<IActionResult>AddFavorite(Guid productId){if(!await db.Products.AnyAsync(x=>x.Id==productId&&x.IsActive))return NotFound();if(!await db.Favorites.AnyAsync(x=>x.UserId==UserId()&&x.ProductId==productId)){db.Favorites.Add(new Favorite{UserId=UserId(),ProductId=productId});await db.SaveChangesAsync();}return NoContent();}
 [HttpDelete("favorites/{productId:guid}")]public async Task<IActionResult>RemoveFavorite(Guid productId){var f=await db.Favorites.SingleOrDefaultAsync(x=>x.UserId==UserId()&&x.ProductId==productId);if(f is not null){db.Favorites.Remove(f);await db.SaveChangesAsync();}return NoContent();}
 [HttpGet("notifications")]public async Task<ActionResult>Notifications([FromQuery]int page=1,[FromQuery]int pageSize=20){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,50);var query=db.Notifications.AsNoTracking().Where(x=>x.UserId==UserId()).OrderByDescending(x=>x.CreatedUtc);var total=await query.CountAsync();return Ok(new{items=await query.Skip((page-1)*pageSize).Take(pageSize).ToListAsync(),page,pageSize,total});}
 [HttpPost("notifications/{id:guid}/read")]public async Task<IActionResult>ReadNotification(Guid id){var n=await db.Notifications.SingleOrDefaultAsync(x=>x.Id==id&&x.UserId==UserId())??throw new KeyNotFoundException("Notification not found.");n.ReadUtc=DateTime.UtcNow;await db.SaveChangesAsync();return NoContent();}
 [HttpPost("notifications/read-all")]public async Task<IActionResult>ReadAllNotifications(){await db.Notifications.Where(x=>x.UserId==UserId()&&x.ReadUtc==null).ExecuteUpdateAsync(x=>x.SetProperty(n=>n.ReadUtc,DateTime.UtcNow));return NoContent();}
 private Guid UserId()=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
}
